import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);

        int n = in.nextInt();
        double p = in.nextDouble();
        int x = 0;
        while (getProb(x, n) < p) {
            x++;
        }
        out.println(x);
        out.close();
    }

    private static double getProb(int x, int n) {
        // Factor x*(n-x) part for efficiency, but same result
        double common = (double) x * (n - x) / (n * (n - 1));
        double termA = 1.5 * common * (n - x - 1) / (n - 2);
        double termB = 3.0 * common * (x - 1) / (n - 2);
        double termC = 1.0 * x * (x - 1) * (x - 2) / (n * (n - 1) * (n - 2));
        return termA + termB + termC;
    }
}

class InputReader {
    private BufferedReader reader;
    private StringTokenizer tokenizer;

    public InputReader(InputStream stream) {
        reader = new BufferedReader(new InputStreamReader(stream));
        tokenizer = null;
    }

    public int nextInt() {
        return Integer.parseInt(next());
    }

    public double nextDouble() {
        return Double.parseDouble(next());
    }

    public String next() {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            try {
                tokenizer = new StringTokenizer(reader.readLine());
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }
        return tokenizer.nextToken();
    }
}
